<script lang="ts">import { onMount } from 'svelte'; import { base } from '$app/paths'; import { RIVALS, rivalAction } from '$lib/rivals/profile'; let selectedId = RIVALS[0].id; let result = ''; onMount(() => { if (new URLSearchParams(location.search).get('run') === '1') result = `${RIVALS[0].name} uses ${rivalAction(RIVALS[0], ['Stronghold']).space}: ${RIVALS[0].reward}`; });</script><main><section><h1>Rivals</h1><p>Deterministic solo and two-player opposition.</p><select bind:value={selectedId}><option value={RIVALS[0].id}>{RIVALS[0].name}</option><option value={RIVALS[1].id}>{RIVALS[1].name}</option></select><a href={`${base}/rivals/?run=1`} data-sveltekit-reload>Run Rival action</a><p role="status">{result || 'Choose a Rival action.'}</p></section></main><style>:global(body){margin:0;background:#17251f;color:#f6efda;font-family:system-ui}main{padding:2rem;min-height:100vh}section{max-width:50rem;margin:10vh auto;padding:3rem;background:#f6efda;color:#20261f}a,select{padding:.8rem;margin:.5rem}a{display:inline-block;background:#6d452d;color:#fff;text-decoration:none}</style>
